<?php session_start();require_once __DIR__.'/../../src/db.php';if(!($_SESSION['admin']??false)){header('Location:/admin/');exit;}$db=db();if($_SERVER['REQUEST_METHOD']==='POST'){if(isset($_POST['create'])){$slug=preg_replace('/[^a-z0-9]+/','-',strtolower($_POST['slug']?:bin2hex(random_bytes(4))));$q=$db->prepare("INSERT INTO tours(title,slug,description,published) VALUES(?,?,?,1)");$q->execute([trim($_POST['title']),$slug,trim($_POST['description'])]);header('Location:/admin/tours.php?edit='.$db->lastInsertId());exit;}if(isset($_POST['add_scene'])){$q=$db->prepare("INSERT INTO tour_scenes(tour_id,panorama_id,title,sort_order) VALUES(?,?,?,?)");$q->execute([(int)$_POST['tour_id'],(int)$_POST['panorama_id'],trim($_POST['scene_title']),time()]);header('Location:/admin/tours.php?edit='.(int)$_POST['tour_id']);exit;}}$tours=$db->query("SELECT * FROM tours ORDER BY id DESC")->fetchAll();$panos=$db->query("SELECT * FROM panoramas ORDER BY title")->fetchAll();$edit=(int)($_GET['edit']??0);$scenes=[];if($edit){$q=$db->prepare("SELECT s.*,p.image,p.title panorama_title FROM tour_scenes s JOIN panoramas p ON p.id=s.panorama_id WHERE s.tour_id=? ORDER BY s.sort_order");$q->execute([$edit]);$scenes=$q->fetchAll();}?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/admin.css"><title>Экскурсии</title></head><body><aside><div class="logo">MINI<span>VR</span></div><a href="/admin/">◉ Панорамы</a><a class="active">◇ Экскурсии</a></aside><main><header><div><small>TOUR BUILDER</small><h1>Экскурсии</h1></div></header><form class="editor" method="post"><input type="hidden" name="create" value="1"><label>Название<input name="title" required></label><label>Slug<input name="slug"></label><label>Описание<textarea name="description"></textarea></label><button class="btn">＋ СОЗДАТЬ ЭКСКУРСИЮ</button></form><div class="table" style="margin-top:28px"><?php foreach($tours as $t):?><div class="row"><div class="grow"><b><?=htmlspecialchars($t['title'])?></b><small>/<?=$t['slug']?></small></div><a href="?edit=<?=$t['id']?>">СЦЕНЫ →</a></div><?php endforeach;?></div><?php if($edit):?><h2 style="margin-top:40px">Сцены экскурсии #<?=$edit?></h2><div class="table"><?php foreach($scenes as $s):?><div class="row"><div class="mini" style="background-image:url('<?=$s['image']?>')"></div><div class="grow"><b><?=htmlspecialchars($s['title']?:$s['panorama_title'])?></b><small>SCENE #<?=$s['id']?></small></div><a href="/admin/hotspots.php?scene=<?=$s['id']?>">HOTSPOTS →</a></div><?php endforeach;?></div><form class="editor" method="post" style="margin-top:15px"><input type="hidden" name="add_scene" value="1"><input type="hidden" name="tour_id" value="<?=$edit?>"><label>Панорама<select name="panorama_id"><?php foreach($panos as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['title'])?></option><?php endforeach;?></select></label><label>Название сцены<input name="scene_title"></label><button class="btn">＋ ДОБАВИТЬ СЦЕНУ</button></form><?php endif;?></main></body></html>